import{c as a,Q as t,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"AgentVerse: Facilitating Multi-Agent Collaboration and Exploring Emergent Behaviors","description":"","frontmatter":{"url":"https://arxiv.org/abs/2308.10848","title":"AgentVerse: Facilitating Multi-Agent Collaboration and Exploring Emergent Behaviors","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2308.10848,"authors":["Weize Chen","Yusheng Su","Jingwei Zuo","Cheng Yang","Chenfei Yuan","Chi-Min Chan","Heyang Yu","Yaxi Lu","Yi-Hsin Hung","Chen Qian","Yujia Qin","Xin Cong","Ruobing Xie","Zhiyuan Liu","Maosong Sun","Jie Zhou"],"domains":["cs.CL","cs.AI","cs.MA"],"pdf_path":"pdfs/2308.10848.pdf","published_date":"2023-08-21T00:00:00.000Z","tags":["multi-agent","collaboration","emergent-behavior","simulation","llm"],"venue":"ICLR 2024"},"headers":[],"relativePath":"research/papers/2023-08-21-agentverse-multi-agent-collaboration-emergent-behaviors-2308-10848.md","filePath":"research/papers/2023-08-21-agentverse-multi-agent-collaboration-emergent-behaviors-2308-10848.md","lastUpdated":1785909234000}'),o={name:"research/papers/2023-08-21-agentverse-multi-agent-collaboration-emergent-behaviors-2308-10848.md"};function r(l,e,s,g,u,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="agentverse-facilitating-multi-agent-collaboration-and-exploring-emergent-behaviors" tabindex="-1">AgentVerse: Facilitating Multi-Agent Collaboration and Exploring Emergent Behaviors <a class="header-anchor" href="#agentverse-facilitating-multi-agent-collaboration-and-exploring-emergent-behaviors" aria-label="Permalink to &quot;AgentVerse: Facilitating Multi-Agent Collaboration and Exploring Emergent Behaviors&quot;">​</a></h1><p><strong>arXiv</strong>: 2308.10848 | <strong>發表</strong>: 2023-08-21 | <strong>PDF</strong>: 2023-08-21-agentverse-multi-agent-collaboration-emergent-behaviors-2308-10848.pdf</p><h2 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h2><p>提出可動態調整 agent 組成的多 agent 框架，涵蓋兩個主軸：（1）<strong>任務求解（task-solving）</strong>：動態組建 agent 團隊解決問題；（2）<strong>模擬（simulation）</strong>：模擬社會行為（如 The Sims 式互動）。框架在協作過程中研究正向（合作湧現）與負向（社會惰化、共識陷阱）兩種湧現行為。</p><h2 id="方法-架構" tabindex="-1">方法 / 架構 <a class="header-anchor" href="#方法-架構" aria-label="Permalink to &quot;方法 / 架構&quot;">​</a></h2><ul><li><strong>四階段 pipeline</strong>：Recruitment（招募適合的 agent 組成）→ Collaborative Decision-Making（集體決策）→ Independent Action Execution（分工執行）→ Evaluation and Evolution（評估並調整 agent 組成）</li><li><strong>動態組成（Dynamic Composition）</strong>：根據任務複雜度與進展，在執行中新增/移除 agent，實現 &quot;greater-than-sum&quot; 效果</li><li><strong>正負湧現管理</strong>：識別 groupthink（群體思維）、free-riding（搭便車）等負向行為並干預</li><li>支援 simulation 模式：多 agent 擁有獨立記憶 + 個性，模擬社交互動</li></ul><h2 id="關鍵發現與數據" tabindex="-1">關鍵發現與數據 <a class="header-anchor" href="#關鍵發現與數據" aria-label="Permalink to &quot;關鍵發現與數據&quot;">​</a></h2><ul><li>Multi-agent 組在複雜推理任務（text games、code generation、logical reasoning）上穩定超越單 agent</li><li>發現 agent 數量並非越多越好：存在最優 team size，過多 agent 引入 coordination overhead</li><li>負向湧現可被結構化 prompt 干預緩解（具體設計見 §4.3）</li><li>Task-solving 和 simulation 雙框架複用同一 agent 架構，驗證通用性</li></ul><h2 id="對-agent-team-設計的啟示" tabindex="-1">對 agent-team 設計的啟示 <a class="header-anchor" href="#對-agent-team-設計的啟示" aria-label="Permalink to &quot;對 agent-team 設計的啟示&quot;">​</a></h2><ol><li><strong>team composition 是一等公民</strong>：不應固定 agent 角色，任務導向的動態招募比靜態分工更適合不確定性高的任務</li><li><strong>監控負向湧現是 orchestrator 職責</strong>：groupthink / free-riding 不會自我消除，需外部干預機制（類 R10 checkpoint）</li><li><strong>simulation 與 task-solving 共用 agent 架構</strong>：說明 memory + persona + interaction 模組是可複用原語</li></ol><h2 id="原文關鍵引用-≤150字" tabindex="-1">原文關鍵引用（≤150字） <a class="header-anchor" href="#原文關鍵引用-≤150字" aria-label="Permalink to &quot;原文關鍵引用（≤150字）&quot;">​</a></h2><blockquote><p>&quot;We propose AgentVerse, a multi-agent framework that can collaboratively and dynamically adjust its composition as a greater-than-the-sum-of-its-parts system... AgentVerse framework can effectively deploy multi-agent groups that outperform a single agent. We also discuss emergent social behaviors among individual agents within a group during collaborative task accomplishment and discuss strategies to leverage positive ones and mitigate negative ones.&quot;</p></blockquote>',12)])])}const d=a(o,[["render",r]]);export{m as __pageData,d as default};
